326	package com.pousadamarealta.pricing;
327	
328	import com.pousadamarealta.domain.RatePlan;
329	import java.math.BigDecimal;
330	import java.math.RoundingMode;
331	import java.time.LocalDate;
332	
333	public class PricingCalculator {
334	    private static final BigDecimal HIGH_SEASON_MULTIPLIER = new BigDecimal("1.20");
335	    private static final BigDecimal NON_REFUNDABLE_DISCOUNT = new BigDecimal("0.15");
336	
337	    public BigDecimal calculateNightPrice(BigDecimal baseRate, LocalDate date) {
338	        if (isHighSeason(date)) {
339	            return round(baseRate.multiply(HIGH_SEASON_MULTIPLIER));
340	        }
341	        return baseRate;
342	    }
343	
344	    public BigDecimal calculateSubtotal(BigDecimal baseRate, LocalDate checkIn, LocalDate checkOut) {
345	        BigDecimal subtotal = BigDecimal.ZERO;
346	        LocalDate current = checkIn;
347	
348	        while (current.isBefore(checkOut)) {
349	            BigDecimal nightPrice = calculateNightPrice(baseRate, current);
350	            subtotal = subtotal.add(nightPrice);
351	            current = current.plusDays(1);
352	        }
353	
354	        return round(subtotal);
355	    }
356	
357	    public BigDecimal calculateDiscount(BigDecimal subtotal, RatePlan ratePlan) {
358	        if (ratePlan == RatePlan.NON_REFUNDABLE) {
359	            return round(subtotal.multiply(NON_REFUNDABLE_DISCOUNT));
360	        }
361	        return BigDecimal.ZERO;
362	    }
363	
364	    public BigDecimal calculateTotal(BigDecimal subtotal, BigDecimal discount) {
365	        return round(subtotal.subtract(discount));
366	    }
367	
368	    private boolean isHighSeason(LocalDate date) {
369	        int month = date.getMonthValue();
370	        int day = date.getDayOfMonth();
371	
372	        if (month == 7) {
373	            return true;
374	        }
375	
376	        if (month == 12 && day >= 15) {
377	            return true;
378	        }
379	
380	        if (month == 1 || month == 2) {
381	            return true;
382	        }
383	
384	        return false;
385	    }
386	
387	    private BigDecimal round(BigDecimal value) {
388	        return value.setScale(2, RoundingMode.HALF_EVEN);
389	    }
390	}

