    29	    public String generateReceipt(Reservation reservation) {
    30	        Room room = roomRepository.findByNumber(reservation.getRoomNumber())
    31	            .orElseThrow();
    32	
    33	        StringBuilder receipt = new StringBuilder();
    34	        receipt.append("Comprovante de reserva nº ").append(reservation.getId()).append("\n");
    35	        receipt.append("Hóspede: ").append(reservation.getGuestName())
    36	               .append(" (CPF ").append(formatCpf(reservation.getGuestCpf())).append(")\n");
    37	        receipt.append("Quarto: ").append(reservation.getRoomNumber())
    38	               .append(" (").append(room.getType().name()).append(")\n");
    39	        receipt.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
    40	               .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
    41	               .append(" | ").append(formatNights(reservation.getNights())).append("\n");
    42	        receipt.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    43	
    44	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    45	            receipt.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
    46	        }
    47	
    48	        receipt.append("Total: ").append(formatMoney(reservation.getTotal()));
    49	
    50	        return receipt.toString();
    51	    }
