    53	    private String formatDate(LocalDate date) {
    54	        return date.format(dateFormatter);
    55	    }
    56	
    57	    private String formatMoney(BigDecimal amount) {
    58	        return "R$ " + moneyFormatter.format(amount);
    59	    }
    60	
    61	    private String formatNights(int nights) {
    62	        return nights == 1 ? "1 diária" : nights + " diárias";
    63	    }
