    65	    private String formatCpf(String cpf) {
    66	        if (cpf.length() == 11) {
    67	            return cpf.substring(0, 3) + "." +
    68	                   cpf.substring(3, 6) + "." +
    69	                   cpf.substring(6, 9) + "-" +
    70	                   cpf.substring(9, 11);
    71	        }
    72	        return cpf;
    73	    }
    74	}
