    82	    public Reservation confirmReservation(Long id) {
    83	        Reservation reservation = getReservation(id);
    84	
    85	        if (reservation.getStatus() != ReservationStatus.PENDING) {
    86	            throw new OperationNotAllowedException();
    87	        }
    88	
    89	        reservation.confirm();
    90	        reservationRepository.update(reservation);
    91	
    92	        messageService.sendConfirmationEmail(reservation);
    93	
    94	        return reservation;
    95	    }
    96	
    97	    public Reservation checkIn(Long id) {
    98	        Reservation reservation = getReservation(id);
    99	
   100	        if (reservation.getStatus() != ReservationStatus.CONFIRMED) {
   101	            throw new OperationNotAllowedException();
   102	        }
   103	
   104	        reservation.checkIn();
   105	        reservationRepository.update(reservation);
   106	
   107	        return reservation;
   108	    }
   109	
   110	    public Reservation checkOut(Long id) {
   111	        Reservation reservation = getReservation(id);
   112	
   113	        if (reservation.getStatus() != ReservationStatus.CHECKED_IN) {
   114	            throw new OperationNotAllowedException();
