    39	        receipt.append("Entrada: ").append(formatDate(reservation.getCheckIn()))
    40	               .append(" | Saída: ").append(formatDate(reservation.getCheckOut()))
    41	               .append(" | ").append(formatNights(reservation.getNights())).append("\n");
    42	        receipt.append("Diárias: ").append(formatMoney(reservation.getSubtotal())).append("\n");
    43	
    44	        if (reservation.getDiscount().compareTo(BigDecimal.ZERO) > 0) {
    45	            receipt.append("Desconto: ").append(formatMoney(reservation.getDiscount())).append("\n");
    46	        }
