    27	
    28	    public Reservation createReservation(int roomNumber, String guestName, String guestEmail,
    29	                                        String guestCpf, LocalDate checkIn, LocalDate checkOut,
    30	                                        int guests, RatePlan ratePlan) {
    31	
    32	        Room room = roomRepository.findByNumber(roomNumber)
    33	            .orElseThrow(() -> new RoomNotFoundException());
    34	
    35	        if (checkOut.isBefore(checkIn) || checkOut.equals(checkIn)) {
    36	            throw new InvalidRequestException("Check-out must be after check-in");
    37	        }
    38	
    39	        if (guests < 1) {
    40	            throw new InvalidRequestException("At least one guest is required");
    41	        }
    42	
    43	        if (guests > room.getCapacity()) {
    44	            throw new CapacityExceededException();
    45	        }
    46	
    47	        List<Reservation> conflicts = reservationRepository.findConflicting(roomNumber, checkIn, checkOut);
    48	        if (!conflicts.isEmpty()) {
    49	            throw new RoomUnavailableException();
    50	        }
    51	
    52	        Reservation reservation = new Reservation();
    53	        reservation.setRoomNumber(roomNumber);
    54	        reservation.setGuestName(guestName);
    55	        reservation.setGuestEmail(guestEmail);
    56	        reservation.setGuestCpf(guestCpf);
    57	        reservation.setCheckIn(checkIn);
    58	        reservation.setCheckOut(checkOut);
    59	        reservation.setGuests(guests);
    60	        reservation.setRatePlan(ratePlan);
    61	
    62	        int nights = (int) ChronoUnit.DAYS.between(checkIn, checkOut);
    63	        reservation.setNights(nights);
    64	
    65	        BigDecimal subtotal = pricingCalculator.calculateSubtotal(room.getNightlyRate(), checkIn, checkOut);
    66	        reservation.setSubtotal(subtotal);
    67	
    68	        BigDecimal discount = pricingCalculator.calculateDiscount(subtotal, ratePlan);
    69	        reservation.setDiscount(discount);
    70	
    71	        BigDecimal total = pricingCalculator.calculateTotal(subtotal, discount);
    72	        reservation.setTotal(total);
    73	
    74	        return reservationRepository.save(reservation);
    75	    }
