   123	    public Reservation cancelReservation(Long id) {
   124	        Reservation reservation = getReservation(id);
   125	
   126	        if (reservation.getStatus() != ReservationStatus.PENDING &&
   127	            reservation.getStatus() != ReservationStatus.CONFIRMED) {
   128	            throw new OperationNotAllowedException();
   129	        }
   130	
   131	        reservation.cancel();
   132	        reservationRepository.update(reservation);
   133	
   134	        return reservation;
